from pathlib import Path
import json,argparse
D=Path(__file__).parent
p=argparse.ArgumentParser();p.add_argument('--skill-root',type=Path,default=D.parents[1]);a=p.parse_args()
runtime='\n'.join((a.skill_root/'assets'/n).read_text(encoding='utf-8-sig') for n in ['chart-motion.js','retained-motion.js','retained-rows.js'])
cases=[('harvest','果园采收 · 数量和品种定位',[{'id':'a','name':'早熟桃','value':92},{'id':'b','name':'李子','value':None},{'id':'c','name':'苹果','value':45},{'id':'d','name':'梨','value':70},{'id':'e','name':'晚熟桃','value':110}],84),('fulfilment','配送点 · 同屏容量与完成率',[{'id':'a','name':'东站','value':120,'rate':92},{'id':'b','name':'北站','value':0,'rate':None},{'id':'c','name':'南站','value':68,'rate':81},{'id':'d','name':'西站','value':94,'rate':97},{'id':'e','name':'新站','value':39,'rate':78}],104)]
for name,title,records,height in cases:
 cfg={'records':records,'height':height,'kind':name,'scopes':{'全部':['a','b','c','d'],'倒序':['d','c','b','a'],'筛选':['c','a'],'新范围':['e','c','a'],'空范围':[]}}
 script='''const cfg=CONFIG;const host=document.getElementById('rows'), status=document.getElementById('status');let count=0;
const app=RetainedRows.create({container:host,records:cfg.records,scopes:cfg.scopes,initial:'全部',rowHeight:cfg.height,duration:620,fallbackFocus:document.getElementById('reset'),statusElement:status,createRow(d){count++;const e=document.createElement('div');e.className='row-content';const button=document.createElement('button');button.className='name';button.dataset.detail=d.id;button.textContent=d.name;button.onclick=()=>document.getElementById('details').textContent=d.name+'：固定原始观测；筛选不修改数值。';e.append(button);const charts=document.createElement('div');charts.className='charts';function metric(value,max,label){const line=document.createElement('div');line.className='metric';const track=document.createElement('div');track.className='track';if(value!==null){const bar=document.createElement('i');bar.className='bar';bar.dataset.value=String(value);bar.style.width=(value/max*100)+'%';track.append(bar)}const t=document.createElement('span');t.textContent=value===null?label+' 未报':label+' '+value;line.append(track,t);charts.append(line)}metric(d.value,120,cfg.kind==='harvest'?'吨':'单');if(cfg.kind==='fulfilment')metric(d.rate,100,'%');e.append(charts);return e;}});
window.app=app;window.rowCreates=()=>count;window.cfg=cfg;window.nodeRefs=new Map(cfg.records.map(d=>[d.id,app.getNode(d.id)]));
for(const b of document.querySelectorAll('[data-scope]'))b.onclick=()=>{for(const q of document.querySelectorAll('[data-scope]'))q.setAttribute('aria-pressed',String(q===b));app.set(b.dataset.scope)};
document.getElementById('destroy').onclick=()=>app.destroy();
'''.replace('CONFIG',json.dumps(cfg,ensure_ascii=False))
 html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>TITLE</title><style>body{font:16px/1.5 system-ui,sans-serif;background:#f6f4ef;color:#213832;margin:40px auto;max-width:980px;padding:0 24px}h1{font-size:30px;margin-bottom:8px}p{max-width:780px;color:#51625c}nav{display:flex;gap:8px;flex-wrap:wrap;margin:26px 0}button{font:inherit;border:1px solid #a9b9ae;background:#fff;padding:9px 16px;border-radius:5px;color:inherit}button:focus-visible{outline:3px solid #da762e;outline-offset:3px}nav [aria-pressed=true]{background:#214c40;color:#fff}#rows{margin:22px 0;border-top:1px solid #b9c6bd}.row-content{height:calc(100% - 8px);display:grid;grid-template-columns:145px 1fr;gap:24px;align-items:center;background:white;padding:10px 18px;box-sizing:border-box;border-bottom:1px solid #d4dcd5}.name{border:0;text-align:left;font-weight:650;padding:8px}.metric{display:grid;grid-template-columns:1fr 100px;align-items:center;gap:16px;min-height:27px}.track{height:12px;background:#e8ede6}.bar{display:block;height:100%;background:#2d8064}.metric:nth-child(2) .bar{background:#bd7c3c}#status{font-size:14px;min-height:24px}#details{min-height:25px}.foot{font-size:13px} @media(max-width:640px){body{margin:24px auto;padding:0 14px}.row-content{grid-template-columns:88px 1fr;gap:10px;padding:8px}.metric{grid-template-columns:1fr 65px;gap:8px;font-size:13px}.name{padding:3px;font-size:14px}}</style><h1>TITLE</h1><p>合成数据。固定观测值只用于检验筛选与重排：同一对象保留原条长，新成员在真实数值上淡入；未报不画成零。比较尺度不随筛选改变。</p><nav><button id="reset" data-scope="全部" aria-pressed="true">全部</button><button data-scope="倒序">倒序</button><button data-scope="筛选">筛选</button><button data-scope="新范围">新范围</button><button data-scope="空范围">空范围</button></nav><p id="status" role="status"></p><div id="rows" aria-label="对象和固定观测值"></div><p id="details" aria-live="polite">点击对象查看说明。</p><button id="destroy">销毁此演示</button><p class="foot">模块验证样例，不是视觉9.5评分或正式经营结论。</p><script>RUNTIME</script><script>SCRIPT</script></html>'''.replace('TITLE',title).replace('RUNTIME',runtime).replace('SCRIPT',script)
 (D/(name+'.html')).write_text(html,encoding='utf-8')
print('Built two self-contained demos')
